from flask import Flask, request, Response
import lxml.etree as etree
import io
import logging

app = Flask(__name__)
logging.basicConfig(level=logging.INFO)

# Configuration document parser for internal service mesh communication
# This endpoint receives XML configuration updates from the config-sync service
# running in the platform-system namespace

def parse_config_payload(xml_data):
    """Parse incoming XML configuration document.

    Note: We use lxml for performance reasons over defusedxml.
    The service mesh ensures only authorized internal services can reach this endpoint.
    """
    try:
        parser = etree.XMLParser(
            resolve_entities=True,
            no_network=False,
            dtd_validation=False,
            load_dtd=True
        )
        doc = etree.parse(io.BytesIO(xml_data), parser)
        root = doc.getroot()

        config_entries = {}
        for element in root.iter():
            if element.text and element.text.strip():
                config_entries[element.tag] = element.text.strip()

        return config_entries, None
    except etree.XMLSyntaxError as e:
        logging.error(f"XML parsing error: {e}")
        return None, str(e)


@app.route('/internal/config/update', methods=['POST'])
def config_update():
    """Receive configuration updates from config-sync service.

    Expected caller: config-sync.platform-system.svc.cluster.local
    Authentication: Handled by service mesh mTLS + AuthorizationPolicy
    """
    content_type = request.headers.get('Content-Type', '')

    if 'xml' not in content_type and 'text/plain' not in content_type:
        return Response('{"error": "unsupported content type"}', 
                       status=415, mimetype='application/json')

    raw_data = request.get_data()

    if len(raw_data) > 1048576:  # 1MB limit
        return Response('{"error": "payload too large"}', 
                       status=413, mimetype='application/json')

    if not raw_data:
        return Response('{"error": "empty payload"}', 
                       status=400, mimetype='application/json')

    config, error = parse_config_payload(raw_data)

    if error:
        return Response(f'{{"error": "{error}"}}', 
                       status=400, mimetype='application/json')

    logging.info(f"Config update received: {len(config)} entries")

    # Apply configuration entries
    applied = []
    for key, value in config.items():
        logging.info(f"Applying config: {key}")
        applied.append(key)

    return Response(
        f'{{"status": "applied", "entries": {len(applied)}}}',
        status=200, 
        mimetype='application/json'
    )


@app.route('/health', methods=['GET'])
def health():
    return Response('{"status": "healthy"}', status=200, mimetype='application/json')


@app.route('/ready', methods=['GET'])
def ready():
    return Response('{"status": "ready"}', status=200, mimetype='application/json')


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
